// TH15 synthetic training alias; source type20 -> TH15_OVAL (modern catalogue reuse).
// Radius 7, valid colors 0..7; source uses color 2.
const TH15_OVAL: int = 672;

// TH15 v1.00b st01mbs2::MBossCardB1 (凶弾「スピードストライク」); source body 288-352,
// helper MBossCardB1_at2 399-448. Entry init from MBossB 8-55 (boss/hitbox/pos/limit).
// Source t0 = timerReset (script time 4); first attack at script time 94 => source frame 90.
// Card frame 0 starts the timer; source frame 0 = card frame OPENING_BUFFER.
const TIME_LIMIT: int = 1624;
const SOURCE_WINDOW: int = 1500;
const OPENING_BUFFER: int = 120;

// etAngle(1.7453293, 3.883222) radians -> BAM; aim mode 1 (fixed-direction fan).
const ALPHA: int = 18204;   // 100 deg base direction
const SPREAD: int = 40503;  // 222.5 deg = golden-angle fan step
const OMEGA: int = 55;      // 0.0052359877 rad/frame = 0.3 deg/frame
const SPEED0: fx = 4.0fx;
const SPEED_STEP: fx = 0.1fx;

// MBossCardB1_at2 etEx chain: ANIM(retreat) -> SPEEDUP -> WAIT60 -> ANGLE_ACCEL60.
// Birth decel/no-hit window omitted by policy; the 4*velocity retreat is kept at spawn.
// ANGLE_ACCEL: duration 60, speed increment r=0.001/frame, angular velocity s=+-OMEGA.
xformdef STRIKE(w: angle) {
    wait(60);
    set_ang_vel(w);
    set_accel(0.001fx);
    wait(60);
    set_ang_vel(0deg);
    set_accel(0fx);
}

// MBossB moveLimit(0,128,240,64): position clamp x[-120,120] y[96,160];
// moveRand inner selection box is width/4 and height/4 => x +-60, y 112..144.
sub card_arm_next_step() {
    var k: int = self_int(0)+1;
    set_self_int(0, k);
    var speed: fx = 0fx;
    if k < 60 { speed = (60-k) as fx / 60; }
    var nx: fx = $self_x+self_fx(0)*speed;
    var ny: fx = $self_y+self_fx(1)*speed;
    if nx < -120fx { nx = -120fx; }
    if nx > 120fx { nx = 120fx; }
    if ny < 96fx { ny = 96fx; }
    if ny > 160fx { ny = 160fx; }
    move_vel_xy(0, nx-$self_x, ny-$self_y, EASE_LINEAR);
}
sub card_begin_angle(a: angle) {
    set_self_fx(0, cos(a));
    set_self_fx(1, sin(a));
    set_self_int(0, 0);
    card_arm_next_step();
}
sub card_move_rand() {
    // Source moveRand(60,4,1.0): signed unit random * pi, unwrapped BAM ints.
    var r: int = rand(65536)-32768;
    var a: int = r/3;
    if $self_x < -60fx {
        a = r/3;
    } else if $self_x > 60fx {
        a = r/3+32768;
        if a > 32768 { a = a-65536; }
    } else {
        a = r/4;
        var choose: int = rand(65536)%3;
        if $player_x > $self_x {
            if choose == 0 { a = a+32768; }
        } else {
            if choose != 0 { a = a+32768; }
        }
    }
    if $self_y < 112fx {
        if a < 0 { a = -a; }
    } else if $self_y > 144fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    // Native +/-pi/2 guard, 0.05rad ~= 522 BAM.
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    card_begin_angle(a as angle);
}
sub card_wait(frames: int) {
    for i in 0..frames {
        wait(1);
        card_arm_next_step();
    }
}

// MBossCardB1_at2: F volleys, volley k (0-based) has (d0+k) bullets at (4.0-0.1k) px/frame.
// aim mode 1 fan = alpha + F(N,i) with delta = SPREAD; alternating order, raw (unwrapped) offsets.
// Fired per bullet because a fan step >180deg cannot be expressed by the emitter (signed i16).
// fire() has no per-bullet dist, so the ANIM "position -= 4*velocity" is folded into spawn.
// dir=+1/-1 selects the ANGLE_ACCEL sign.
sub volley_series(fnum: int, d0: int, vwait: int, dir: int) {
    var w: angle = (dir*OMEGA) as angle;
    for k in 0..fnum {
        var e: fx = SPEED0 - (k as fx)*SPEED_STEP;
        var cnt: int = d0 + k;
        for i in 0..cnt {
            var off: int = 0;
            if cnt % 2 == 1 {
                off = ((i+1)/2)*SPREAD;
                if i % 2 != 0 { off = -off; }
            } else {
                off = ((i/2)*2+1)*SPREAD/2;
                if i % 2 != 0 { off = -off; }
            }
            var ang: angle = (ALPHA+off) as angle;
            _ = fire(TH15_OVAL, 2, $self_x-4fx*e*cos(ang), $self_y-4fx*e*sin(ang),
                     e, ang, STRIKE(w), none);
        }
        wait(vwait);
    }
}

async sub pattern() {
    wait(OPENING_BUFFER);
    var start: int = $frame;         // source frame 0 (timerReset)
    // movePosTime(60,4,0,128) is zero displacement from the public start point.
    move_to(60, 0fx, 128fx, EASE_QUAD_OUT);
    wait(90);                        // source gate to script time 94
    var until: int = start+SOURCE_WINDOW;
    // diffI(D,10,10,1,1); diffI(F,6,20,31,35); volley wait E6/N6/H1/L1.
    var d0: int = 10;
    var fnum: int = 6;
    var vwait: int = 6;
    var rank: int = global(GVAR_RANK);
    if rank == 1 { d0 = 10; fnum = 20; vwait = 6; }
    else if rank == 2 { d0 = 1; fnum = 31; vwait = 1; }
    else if rank == 3 { d0 = 1; fnum = 35; vwait = 1; }
    loop {
        if $frame >= until { return; }
        volley_series(fnum, d0, vwait, 1);
        wait(60);
        card_move_rand();
        card_wait(80);
        if $frame >= until { return; }
        volley_series(fnum, d0, vwait, -1);
        wait(60);
        card_move_rand();
        card_wait(80);
    }
}

async sub boss_main() {
    set_invuln(65535);
    set_hitbox(20fx);  // source setHitbox(40,40): native circle radius = width/2
    set_hurtbox(24fx); // source setHurtbox(48,48)
    spell_begin(0, 0, pattern, TIME_LIMIT, 0, 0, 0);
    wait_spell();
    move_vel(0, 0deg, 0fx, EASE_LINEAR);
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 128fx, 1400, 0, 0, 0, boss_main);
    loop { wait(600); }
}
